PRAGMA foreign_keys = ON;
CREATE TABLE "user" (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE firms (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', owner_id TEXT NOT NULL UNIQUE REFERENCES "user"(id), created_at TEXT NOT NULL);
CREATE TABLE workspace_members (user_id TEXT PRIMARY KEY REFERENCES "user"(id), firm_id TEXT NOT NULL REFERENCES firms(id), email TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','member')), created_at TEXT NOT NULL);
CREATE INDEX members_firm ON workspace_members(firm_id);
CREATE TABLE workspace_invites (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, UNIQUE(firm_id,email));
CREATE TABLE api_keys (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), user_id TEXT NOT NULL REFERENCES "user"(id), name TEXT NOT NULL, prefix TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, scopes TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, last_used_at TEXT, revoked_at TEXT);
CREATE INDEX keys_firm ON api_keys(firm_id);
CREATE TABLE recovery_codes (user_id TEXT PRIMARY KEY REFERENCES "user"(id), token_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE agents (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', agency TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT 'teal', created_at TEXT NOT NULL, UNIQUE(id,firm_id));
CREATE INDEX agents_firm ON agents(firm_id);
CREATE TABLE cases (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), ref TEXT NOT NULL COLLATE NOCASE, buyer TEXT NOT NULL, seller TEXT NOT NULL DEFAULT '', property TEXT NOT NULL DEFAULT '', type TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, agent_id TEXT, owner TEXT NOT NULL DEFAULT '', due_date TEXT, next_step TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', value REAL NOT NULL DEFAULT 0 CHECK(value>=0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id,firm_id), UNIQUE(firm_id,ref), FOREIGN KEY(agent_id,firm_id) REFERENCES agents(id,firm_id));
CREATE INDEX cases_firm ON cases(firm_id,updated_at DESC);
CREATE TABLE tasks (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), case_id TEXT, title TEXT NOT NULL, due_date TEXT, assignee TEXT NOT NULL DEFAULT '', completed INTEGER NOT NULL DEFAULT 0, priority TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE INDEX tasks_firm ON tasks(firm_id);
CREATE TABLE activities (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), case_id TEXT, title TEXT NOT NULL, detail TEXT NOT NULL, kind TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX activities_firm ON activities(firm_id,created_at DESC);
CREATE TABLE documents (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), case_id TEXT NOT NULL, filename TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, content_type TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL, actor TEXT NOT NULL, FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE INDEX documents_firm ON documents(firm_id,case_id);
CREATE TABLE whatsapp_settings (firm_id TEXT PRIMARY KEY REFERENCES firms(id), phone_number_id TEXT NOT NULL DEFAULT '', access_token TEXT, app_secret TEXT, verify_token_hash TEXT, enabled INTEGER NOT NULL DEFAULT 0, dry_run INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE whatsapp_contacts (firm_id TEXT NOT NULL REFERENCES firms(id), agent_id TEXT NOT NULL, phone TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, consent INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(firm_id,agent_id), UNIQUE(firm_id,phone), FOREIGN KEY(agent_id,firm_id) REFERENCES agents(id,firm_id));
CREATE TABLE whatsapp_messages (id TEXT PRIMARY KEY, firm_id TEXT NOT NULL REFERENCES firms(id), case_id TEXT, phone TEXT NOT NULL, direction TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL, provider_id TEXT, idempotency_key TEXT, created_at TEXT NOT NULL, actor TEXT NOT NULL, UNIQUE(firm_id,idempotency_key), UNIQUE(firm_id,provider_id), FOREIGN KEY(case_id,firm_id) REFERENCES cases(id,firm_id));
CREATE INDEX messages_firm ON whatsapp_messages(firm_id,created_at DESC);
CREATE TABLE api_usage (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
